import type { WhatsAppClient } from "@photon-ai/whatsapp-business";

// `@photon-ai/whatsapp-business` clients don't expose the `phoneNumberId` they
// were created with, but each client — a direct-mode client or a cloud-mode
// per-line proxy — is bound to exactly one line. Record that mapping at
// creation so an inbound message can be tagged with the line it arrived on
// (surfaced as `space.line`). Keyed by the client object; entries drop when the
// client is GC'd.
const clientLine = new WeakMap<WhatsAppClient, string>();

export const registerClientLine = (
  client: WhatsAppClient,
  phoneNumberId: string
): void => {
  clientLine.set(client, phoneNumberId);
};

export const lineForClient = (client: WhatsAppClient): string | undefined =>
  clientLine.get(client);
