208	const buildClientProxy = (
209	  state: LineState,
210	  refresh: () => Promise<void>
211	): WhatsAppClient => {
212	  const forwarder = <T extends object>(pick: (c: WhatsAppClient) => T): T =>
213	    new Proxy({} as T, {
214	      get:
215	        (_, prop: string | symbol) =>
216	        async (...args: unknown[]) => {
217	          await refresh();
218	          const target = pick(state.current) as Record<
219	            string | symbol,
220	            unknown
221	          >;
222	          const fn = target[prop] as (...a: unknown[]) => unknown;
223	          return Reflect.apply(fn, pick(state.current), args);
224	        },
225	    });
226	
227	  const events = {
228	    fetchMissed: async (
229	      opts: Parameters<WhatsAppClient["events"]["fetchMissed"]>[0]
230	    ) => {
231	      await refresh();
232	      return state.current.events.fetchMissed(opts);
233	    },
234	    subscribe: (options?: SubscribeOptions) =>
235	      resubscribableStream(state, options),
236	  } as unknown as WhatsAppClient["events"];
237	
238	  return {
239	    events,
240	    media: forwarder((c) => c.media),
241	    messages: forwarder((c) => c.messages),
242	    close: async () => {
243	      for (const sub of state.subscriptions) {
244	        sub.close();
245	      }
246	      await state.current.close();
247	    },
248	    [Symbol.asyncDispose]: async () => {
249	      for (const sub of state.subscriptions) {
250	        sub.close();
251	      }
252	      await state.current.close();
253	    },
254	  };
255	};
