257	interface ResubscribeContext {
258	  emit: (event: WhatsAppEvent) => Promise<void>;
259	  getCurrent: () => WhatsAppClient;
260	  isClosed: () => boolean;
261	  options?: SubscribeOptions;
262	  setActive: (stream: TypedEventStream<WhatsAppEvent> | undefined) => void;
263	  swapVersion: () => number;
264	  waitForSwap: (version: number) => Promise<void>;
265	}
266	
267	type PumpResult = "closed" | "ended" | "error" | "swap";
268	
269	type NextResult =
270	  | { type: "next"; result: IteratorResult<WhatsAppEvent> }
271	  | { type: "error"; error: unknown };
272	
273	const settleNext = (
274	  next: Promise<IteratorResult<WhatsAppEvent>>
275	): Promise<NextResult> =>
276	  next.then(
277	    (result) => ({ type: "next", result }),
278	    (error) => ({ type: "error", error })
279	  );
280	
281	const closeStream = (stream: TypedEventStream<WhatsAppEvent>): void => {
282	  stream.close().catch(ignoreCleanupError);
283	};
284	
285	const returnIterator = (iterator: AsyncIterator<WhatsAppEvent>): void => {
286	  iterator.return?.(undefined).catch(ignoreCleanupError);
287	};
288	
289	const pumpOnce = async (ctx: ResubscribeContext): Promise<PumpResult> => {
290	  const sub = ctx.getCurrent().events.subscribe(ctx.options);
291	  const iterator = sub[Symbol.asyncIterator]();
292	  const swapVersion = ctx.swapVersion();
293	  ctx.setActive(sub);
294	  try {
295	    while (!ctx.isClosed()) {
296	      const result = await Promise.race([
297	        settleNext(iterator.next()),
298	        ctx.waitForSwap(swapVersion).then(() => ({ type: "swap" as const })),
299	      ]);
300	
301	      if (result.type === "swap") {
302	        closeStream(sub);
303	        returnIterator(iterator);
304	        return ctx.isClosed() ? "closed" : "swap";
305	      }
306	
307	      if (result.type === "error") {
308	        throw result.error;
309	      }
310	
311	      if (result.result.done) {
312	        return ctx.isClosed() ? "closed" : "ended";
313	      }
314	
315	      await ctx.emit(result.result.value);
316	    }
317	    return "closed";
318	  } catch (error) {
319	    closeStream(sub);
320	    returnIterator(iterator);
321	    streamLog.warn(
322	      "whatsapp event stream interrupted; resubscribing",
323	      {
324	        "spectrum.whatsapp.resubscribe_in_ms": RESUBSCRIBE_BACKOFF_MS,
325	        ...errorAttrs(error),
326	      },
327	      error
328	    );
329	    return ctx.isClosed() ? "closed" : "error";
330	  } finally {
331	    ctx.setActive(undefined);
332	  }
333	};
