335	// Returns a TypedEventStream that stays open across client swaps: on swap we
336	// close the underlying subscription and the worker loop re-subscribes against
337	// `state.current`.
338	const resubscribableStream = (
339	  state: LineState,
340	  options?: SubscribeOptions
341	): TypedEventStream<WhatsAppEvent> => {
342	  let closed = false;
343	  let active: TypedEventStream<WhatsAppEvent> | undefined;
344	  let swapVersion = 0;
345	  let wakeSwap: (() => void) | undefined;
346	
347	  const wake = () => {
348	    wakeSwap?.();
349	    wakeSwap = undefined;
350	  };
351	
352	  const requestResubscribe = () => {
353	    swapVersion += 1;
354	    wake();
355	    active?.close().catch(ignoreCleanupError);
356	  };
357	
358	  const source = stream<WhatsAppEvent>((emit, end) => {
359	    const ctx: ResubscribeContext = {
360	      emit,
361	      getCurrent: () => state.current,
362	      isClosed: () => closed,
363	      options,
364	      setActive: (s) => {
365	        active = s;
366	      },
367	      swapVersion: () => swapVersion,
368	      waitForSwap: (version) => {
369	        if (closed || swapVersion !== version) {
370	          return Promise.resolve();
371	        }
372	        return new Promise((resolve) => {
373	          wakeSwap = resolve;
374	        });
375	      },
376	    };
377	    const pump = (async () => {
378	      while (!closed) {
379	        const result = await pumpOnce(ctx);
380	        if (!closed && result !== "swap") {
381	          await new Promise((r) => setTimeout(r, RESUBSCRIBE_BACKOFF_MS));
382	        }
383	      }
384	      end();
385	    })();
386	
387	    return async () => {
388	      closed = true;
389	      wake();
390	      active?.close().catch(ignoreCleanupError);
391	      active = undefined;
392	      state.subscriptions.delete(subscription);
393	      await pump;
394	    };
395	  });
396	
397	  const subscription: LineSubscription = {
398	    close: () => {
399	      closed = true;
400	      wake();
401	      active?.close().catch(ignoreCleanupError);
402	    },
403	    swap: () => {
404	      // Force the worker loop to start a fresh RPC against state.current even
405	      // if the SDK iterator is stuck waiting for its old stream to finish.
406	      requestResubscribe();
407	    },
408	  };
409	  state.subscriptions.add(subscription);
410	
411	  return new TypedEventStream<WhatsAppEvent>(source, async () => {
412	    closed = true;
413	    wake();
414	    active?.close().catch(ignoreCleanupError);
415	    state.subscriptions.delete(subscription);
416	    await source.close();
417	  });
418	};
