75	const cachePoll = (
76	  client: WhatsAppClient,
77	  messageId: string,
78	  poll: Poll
79	): void => {
80	  const cache = getPollCache(client);
81	  if (cache.has(messageId)) {
82	    cache.delete(messageId);
83	  }
84	  cache.set(messageId, poll);
85	  if (cache.size > MAX_POLL_CACHE_SIZE) {
86	    const first = cache.keys().next().value;
87	    if (first !== undefined) {
88	      cache.delete(first);
89	    }
90	  }
