248	const toMessages = (
249	  client: WhatsAppClient,
250	  msg: InboundMessage
251	): WhatsAppMessage[] => {
252	  const base = {
253	    sender: { id: msg.from },
254	    space: { id: msg.from, line: lineForClient(client) },
255	    timestamp: msg.timestamp,
256	  };
257	  if (msg.content.type === "contacts") {
258	    const multi = msg.content.contacts.length > 1;
259	    return msg.content.contacts.map((card, index) => ({
260	      ...base,
261	      id: multi ? `${msg.id}:${index}` : msg.id,
262	      content: waContactToSpectrum(card),
263	    }));
264	  }
265	  return [
266	    {
267	      ...base,
268	      id: msg.id,
269	      content: mapContent(client, msg),
270	    },
271	  ];
