274	const mapContent = (client: WhatsAppClient, msg: InboundMessage): Content => {
275	  const { content } = msg;
276	  switch (content.type) {
277	    case "text":
278	      return asText(content.body);
279	    case "image":
280	    case "video":
281	    case "audio":
282	    case "document":
283	      return lazyMedia(client, content.media);
284	    case "sticker":
285	      return asCustom({ whatsapp_type: "sticker", ...content.sticker });
286	    case "location":
287	      return asCustom({ whatsapp_type: "location", ...content.location });
288	    case "reaction": {
289	      // WhatsApp reaction events carry only the target message id; synthesize
290	      // a minimal target Message shape. Core's wrapProviderMessage inflates
291	      // this into a full Message with react/reply methods at emit time.
292	      const stubTarget = {
293	        id: content.reaction.messageId,
294	        content: asCustom({ whatsapp_type: "reaction-target", stub: true }),
295	      };
296	      return asReaction({
297	        emoji: content.reaction.emoji,
298	        target: stubTarget as Parameters<typeof asReaction>[0]["target"],
299	      });
300	    }
301	    case "interactive": {
302	      const inter = content.interactive;
303	      if (inter.type === "button_reply" || inter.type === "list_reply") {
304	        const poll =
305	          msg.context?.id === undefined
306	            ? undefined
307	            : getPollCache(client).get(msg.context.id);
308	        const optionIndex = optionIndexFromId(inter.reply.id);
309	        const option =
310	          optionIndex === undefined ? undefined : poll?.options[optionIndex];
311	        if (poll && option) {
312	          return asPollOption({ poll, option, selected: true });
313	        }
314	      }
315	      return asCustom({ whatsapp_type: "interactive", ...inter });
316	    }
317	    case "button":
318	      return asCustom({ whatsapp_type: "button", ...content.button });
319	    case "order":
320	      return asCustom({ whatsapp_type: "order", ...content.order });
321	    case "system":
322	      return asCustom({ whatsapp_type: "system", ...content.system });
323	    default:
324	      return asCustom({ whatsapp_type: "unknown" });
325	  }
326	};
