490	const clientStream = (
491	  client: WhatsAppClient
492	): ManagedStream<WhatsAppMessage> => {
493	  const eventStream = client.events
494	    .subscribe({
495	      // The client heals disconnects AND silently stalled streams on its own
496	      // (its stallTimeoutMs converts missed heartbeats into a reconnect with
497	      // cursor gap-fill). That recovery is invisible from out here, so
498	      // surface each attempt for operators — without this a stalled stream
499	      // heals with zero log evidence and a flapping upstream is
500	      // indistinguishable from a healthy one.
501	      reconnect: {
502	        onReconnect: (attempt) => {
503	          streamLog.warn("whatsapp live stream reconnecting", {
504	            "spectrum.whatsapp.reconnect_attempt": attempt,
505	          });
506	        },
507	      },
508	    })
509	    .filter(
510	      (e): e is Extract<typeof e, { type: "message" }> => e.type === "message"
511	    );
512	
513	  return stream<WhatsAppMessage>((emit, end) => {
514	    const pump = (async () => {
515	      try {
516	        for await (const event of eventStream) {
517	          for (const m of toMessages(client, event.message)) {
518	            await emit(m);
519	          }
520	        }
521	        end();
522	      } catch (e) {
523	        end(e);
524	      }
525	    })();
526	    return async () => {
527	      await eventStream.close();
528	      await pump;
529	    };
530	  });
531	};
