537	export const send = async (
538	  clients: WhatsAppClients,
539	  spaceId: string,
540	  content: Content
541	): Promise<ProviderMessageRecord | undefined> => {
542	  if (content.type === "reply") {
543	    return await replyToMessage(
544	      clients,
545	      spaceId,
546	      content.target.id,
547	      content.content
548	    );
549	  }
550	  if (content.type === "reaction") {
551	    return await reactToMessage(clients, spaceId, content);
552	  }
553	  if (content.type === "typing") {
554	    // WhatsApp Business has no typing-indicator API. Silently ignore so
555	    // `space.startTyping()` / `space.responding()` work portably across
556	    // platforms — typing is a hint, not a critical message.
557	    return;
558	  }
559	  if (content.type === "read") {
560	    // Cumulative receipt: the Cloud API marks `target` and every earlier
561	    // message in the conversation as read (blue ticks for the sender).
562	    await primary(clients).messages.markRead(content.target.id);
563	    return;
564	  }
565	  const client = primary(clients);
566	  switch (content.type) {
567	    case "text":
568	      return toRecord(
569	        await client.messages.send({ to: spaceId, text: content.text }),
570	        spaceId,
571	        content
572	      );
573	    case "attachment": {
574	      const { mediaId } = await client.media.upload({
575	        file: await content.read(),
576	        mimeType: content.mimeType,
577	        filename: content.name,
578	      });
579	      const mediaType = mimeToMediaType(content.mimeType);
580	      const mediaPayload =
581	        mediaType === "document"
582	          ? { id: mediaId, filename: content.name }
583	          : { id: mediaId };
584	      return toRecord(
585	        await client.messages.send({
586	          to: spaceId,
587	          [mediaType]: mediaPayload,
588	        } as Parameters<typeof client.messages.send>[0]),
589	        spaceId,
590	        content
591	      );
592	    }
593	    case "contact":
594	      return toRecord(
595	        await client.messages.send({
596	          to: spaceId,
597	          contacts: [contactToWa(content)],
598	        }),
599	        spaceId,
600	        content
601	      );
602	    case "voice": {
603	      const { mediaId } = await client.media.upload({
604	        file: await content.read(),
605	        mimeType: content.mimeType,
606	        filename: voiceFilename(content),
607	      });
608	      return toRecord(
609	        await client.messages.send({
610	          to: spaceId,
611	          audio: { id: mediaId },
612	        } as Parameters<typeof client.messages.send>[0]),
613	        spaceId,
614	        content
615	      );
616	    }
617	    case "poll": {
618	      const result = await client.messages.send({
619	        to: spaceId,
620	        interactive: pollToInteractive(content),
621	      });
622	      cachePoll(client, result.messageId, content);
623	      return toRecord(result, spaceId, content);
624	    }
625	    case "app":
626	      // No mini-app surface on WhatsApp — send the bare URL as text.
627	      return toRecord(
628	        await client.messages.send({ to: spaceId, text: await content.url() }),
629	        spaceId,
630	        content
631	      );
632	    default:
633	      throw UnsupportedError.content(content.type);
634	  }
635	};
